from pathlib import Path
import gzip,json,sys,copy,hashlib,math
from types import SimpleNamespace
work=Path('E:/GITHUB/CFTUV/.claude/worktrees/agent-a4f70aeefab096d07')
sys.path.insert(0,str(work/'artifacts/perf_prepare_diag'))
import env
from cftuv.envelope_production_view import build_domain_view
p=Path(__file__).parent/'results'
a=json.loads(gzip.decompress((p/'base_material.json.gz').read_bytes()))['rows']
b=json.loads(gzip.decompress((p/'new_material.json.gz').read_bytes()))['rows']
old={(r['density'],r['patch_id']):r for r in a}
def keys(c):return tuple(v['value'] for v in c['ordered_vert_keys'])
def ns(o):
    if isinstance(o,dict):return SimpleNamespace(**{k:ns(v) for k,v in o.items()})
    if isinstance(o,list):return [ns(v) for v in o]
    return o
def view(batch,patch):
    # Каждому ключу/якорю — своя допустимая единичная нормаль: подмена якоря уже не спрячется за константой.
    trace=[]
    normals=[]
    for vertex in sorted(batch['vertices'],key=lambda v:v['vert_key']['value']):
        key=vertex['vert_key']['value'];anchor=vertex['semantic_location_ref']['value']
        bits=hashlib.sha256((key+'|'+anchor).encode()).digest()
        raw=((bits[0]+1)/257.,(bits[1]+1)/257.,1.)
        length=math.sqrt(sum(x*x for x in raw));normal=tuple(x/length for x in raw)
        normals.append((key,normal));trace.append(['normal_for_anchor',key,anchor,normal])
    class Source(SimpleNamespace):
        def __getattribute__(self,name):
            if name in ('normal','source_normal','vertex_normals','patch_id'):trace.append(['result_field',name])
            return super().__getattribute__(name)
    result=Source(batch=ns(batch),normal=(0.,0.,1.),source_normal=(0.,0.,1.),vertex_normals=tuple(normals),patch_id=patch)
    return build_domain_view(result),trace
rows=[]
for fresh in b:
    base=old[fresh['density'],fresh['patch_id']]
    x=base['evidence']['batch'];y=fresh['evidence']['batch']
    remap={v['id']:fresh['identity_trace'][k]['id'] for k,v in base['identity_trace'].items()}
    def renamed(o):
        if isinstance(o,str):
            for previous_id,current_id in remap.items():o=o.replace(previous_id,current_id)
            return o
        if isinstance(o,dict):return {k:renamed(v) for k,v in o.items()}
        if isinstance(o,list):return [renamed(v) for v in o]
        return o
    previous={min(keys(c),keys(c)[::-1]):c for c in x['interface_chains']}
    assert len(previous)==len(x['interface_chains'])==len(y['interface_chains'])
    changed=[]
    for chain in y['interface_chains']:
        k=keys(chain);prior=previous[min(k,k[::-1])]
        if keys(prior)!=k:
            assert keys(prior)==k[::-1]
            ends=[]
            for batch in (x,y):
                vertex={v['vert_key']['value']:v for v in batch['vertices']}
                ends.append([vertex[v] for v in sorted({k[0],k[-1]})])
            # У якорей меняются только lineage claim:envelope-instance по уже измеренной карте V2.
            old_ends=renamed(ends[0])
            for end in old_ends:end['provenance']['lineage_ids'].sort(key=repr)
            assert old_ends==ends[1]
            adjacent=[]
            for batch in (x,y):
                adjacent.append([{'region':f['semantic_region_id'],'owner':f['ownership_claim_id'],'lineage':f['provenance']['lineage_ids'],'keys':f['ordered_vert_keys'],'uv':f['uv_facts']} for f in batch['faces'] if set(k[:2])<=set(v['value'] for v in f['ordered_vert_keys'])])
            changed.append({'old':prior,'new':chain,'old_endpoint_anchors':ends[0],'new_endpoint_anchors':ends[1],'anchors_equal_after_measured_instance_id_map':True,'old_adjacent':adjacent[0],'new_adjacent':adjacent[1]})
    host_checks=[];old_new=[]
    for batch in (x,y):
        reverse=copy.deepcopy(batch)
        for c in reverse['interface_chains']:c['ordered_vert_keys'].reverse()
        original_view,original_trace=view(batch,fresh['patch_id']);reversed_view,reversed_trace=view(reverse,fresh['patch_id'])
        assert original_view.failure is None and reversed_view==original_view
        assert original_trace==reversed_trace
        old_new.append((original_view.vertices,original_trace))
        host_checks.append(True)
    assert old_new[0]==old_new[1]
    normal_trace=old_new[0][1]
    rows.append({'density':fresh['density'],'patch_id':fresh['patch_id'],'chain_edges_exactly_equal':True,'host_arrays_identical_when_all_interfaces_reversed':host_checks,'old_new_reversed_provider_trace_equal':True,'old_new_positions_normals_anchors_equal':True,'normal_provider_trace_sha256':hashlib.sha256(repr(normal_trace).encode()).hexdigest(),'different_anchor_normals':len({tuple(x[3]) for x in normal_trace if x[0]=='normal_for_anchor'}),'reversed_chains':changed})
(p/'chain_orientation_manifest.json').write_text(json.dumps({'schema':'CANON_V2_INTERFACE_REPRESENTATION_SHIFT_V1','consumer_test_normal':'distinct unit normals selected by SHA256(vertex key|semantic location anchor); provider arguments, consumed result fields, output vertex/normal/anchor correspondence identical old/new/reversed','rows':rows},indent=2),encoding='utf8')
print('checked',len(rows),'reversed domain rows',sum(bool(r['reversed_chains']) for r in rows),'reversed chains',sum(len(r['reversed_chains']) for r in rows))

