from pathlib import Path
import json,sys,hashlib
base=json.loads(Path(sys.argv[1]).read_text());new=json.loads(Path(sys.argv[2]).read_text())
def key(row):return row['source'],row['density'],row['patch_id']
old={key(r):r for r in base['rows']};fresh={key(r):r for r in new['rows']}
problems=[];affected=[];geometry_changes=[];price_changes=[];summary=[]
for k in sorted(old.keys() & fresh.keys()):
    a,b=old[k],fresh[k];ta,tb=a['identity_trace'],b['identity_trace']
    if ta.keys()!=tb.keys():problems.append([k,'identity value sets changed'])
    changes=[]
    for name in sorted(ta.keys() & tb.keys()):
        x,y=ta[name],tb[name]
        if x!=y:
            if x['alpha_value']!=y['alpha_value'] or x['args']!=y['args']:problems.append([k,'identity arguments changed',name])
            if x['alpha_value'][0]!='SQ':problems.append([k,'rational identity changed',name])
            changes.append({'value_key':name,'kind':x['kind'],'args':x['args'],'value':x['alpha_value'],'old_text':x['alpha_text'],'new_text':y['alpha_text'],'old_id':x['id'],'new_id':y['id']})
    answer_changes=[f for f in a['answer'] if a['answer'][f]!=b['answer'].get(f)]
    permitted={'fp_geometry','fp_geometry_value'}
    unexpected=set(answer_changes)-permitted
    if unexpected:problems.append([k,'answer changed outside alpha-derived identity',sorted(unexpected)])
    if answer_changes:geometry_changes.append([k,answer_changes])
    prices={f:[a['price'].get(f),b['price'].get(f)] for f in set(a['price'])|set(b['price']) if (f.startswith('EXACT_WORK_') or f=='leaked_unbudgeted') and a['price'].get(f)!=b['price'].get(f)}
    if prices:price_changes.append([k,prices]);problems.append([k,'budget price changed',prices])
    if changes:affected.append({'source':k[0],'density':k[1],'patch_id':k[2],'identity_changes':changes,'answer_fields_changed':answer_changes,'value_geometry_equal':not unexpected})
receipt={'schema':'EXACT_SCALAR_TEXT_CANON_V2_AFFECTED_DOMAINS_V1','base_root':base['root'],'new_root':new['root'],'base_code_identity':base['kernel_code_identity'],'new_code_identity':new['kernel_code_identity'],'base_rows':len(old),'new_rows':len(fresh),'compared':len(old.keys()&fresh.keys()),'complete':old.keys()==fresh.keys(),'affected_domains':affected,'raw_geometry_digest_changes':geometry_changes,'budget_price_changes':price_changes,'unexpected':problems}
if len(sys.argv)>3:Path(sys.argv[3]).write_text(json.dumps(receipt,indent=2),encoding='utf8')
print(json.dumps({'compared':receipt['compared'],'complete':receipt['complete'],'affected_domain_rows':len(affected),'unique_affected_domains':len({(r['source'],r['patch_id']) for r in affected}),'changed_digest_rows':len(geometry_changes),'unexpected':problems[:10]}))

