from pathlib import Path
import gzip,json,sys,hashlib
root=Path(__file__).parent/'results'
a=json.loads(gzip.decompress((root/'base_material.json.gz').read_bytes()))
b=json.loads(gzip.decompress((root/'new_material.json.gz').read_bytes()))
old={(r['density'],r['patch_id']):r for r in a['rows']}
rows=[];problems=[]
def digest(o):return hashlib.sha256(json.dumps(o,sort_keys=True,separators=(',',':')).encode()).hexdigest()
for fresh in b['rows']:
    key=fresh['density'],fresh['patch_id'];base=old[key]
    changed={k:[base.get(k),fresh.get(k)] for k in set(base)|set(fresh) if base.get(k)!=fresh.get(k) and k not in ('evidence','identity_trace','symbolic_backend_report') and not k.endswith('seconds')}
    unexpected=set(changed)-{'content_digest','semantic_digest'}
    if unexpected:problems.append([key,'non-digest fields',sorted(unexpected)])
    left=base['evidence']['geometry_values'];right=fresh['evidence']['geometry_values']
    directional_interfaces_equal=left['interface_chains']==right['interface_chains']
    def physical_geometry(view):
        result=dict(view)
        result['interface_chains']=sorted([min((c,c[::-1]),key=repr) for c in view['interface_chains']],key=repr)
        return result
    fields={k:base['evidence'].get(k)==fresh['evidence'].get(k) for k in ('budget','sign_counts')}
    fields['geometry_values']=physical_geometry(left)==physical_geometry(right)
    if not all(fields.values()):problems.append([key,'geometry/value/price changed',fields])
    if key[1]==2 and changed:problems.append([key,'rational control changed'])
    rows.append({'density':key[0],'patch_id':key[1],'digests':{k:{'old':base.get(k),'new':fresh.get(k)} for k in ('content_digest','semantic_digest','offset_normals_digest')},'exact_equality':fields,'geometry_values_sha256':digest(physical_geometry(right)),'directional_interface_chains_equal':directional_interfaces_equal,'named_representation_shift':None if directional_interfaces_equal else 'CANON_V2_INTERFACE_REPRESENTATION_SHIFT_V1','budget':fresh['evidence'].get('budget'),'sign_counts':fresh['evidence'].get('sign_counts'),'non_digest_changes':{k:v for k,v in changed.items() if k not in ('content_digest','semantic_digest')}})
receipt={'schema':'EXACT_SCALAR_TEXT_CANON_V2_MATERIALIZED_VALUES_V1','base_root':a['root'],'new_root':b['root'],'topology':a['topology'],'complete':len(rows)==len(old)==27,'compared':len(rows),'rows':rows,'unexpected':problems}
(root/'material_manifest.json').write_text(json.dumps(receipt,indent=2),encoding='utf8')
print(json.dumps({'compared':len(rows),'complete':receipt['complete'],'unexpected':problems,'changed_digest_rows':sum(r['digests']['content_digest']['old']!=r['digests']['content_digest']['new'] for r in rows)}))

