from pathlib import Path
import sys,runpy,json,dataclasses,gzip,hashlib
sys.argv.append('setup')
g=runpy.run_path(str(Path(__file__).with_name('differential.py')))
root=g['root'];out=g['out'];normal=g['normal'];trace=g['trace'];aliases=g['aliases']
sys.path.insert(0,str(root/'artifacts/materialize_sweep'))
import sweep
from cftuv_envelope.materialize import domain as material
from cftuv_envelope import exact_sqrt_sum as canon
original=material.materialize_domain
capture={}
def primitive(o):
    if dataclasses.is_dataclass(o):return {f.name:primitive(getattr(o,f.name)) for f in dataclasses.fields(o)}
    if isinstance(o,(frozenset,set)):return sorted(map(primitive,o),key=repr)
    if isinstance(o,(tuple,list)):return list(map(primitive,o))
    if o is None or isinstance(o,(bool,int,float,str)):return o
    return repr(o)
def provenance(p):return primitive((p.source_face_ids,p.physical_edge_ids,p.chain_use_ids))
def cycle(items):return min((items[i:]+items[:i] for i in range(len(items))),key=repr) if items else []
def observed(*args,**kwargs):
    result=original(*args,**kwargs)
    capture['budget']={k:v for k,v in result.counters if k.startswith('EXACT_WORK_')}
    capture['sign_counts']=dict(canon.SIGN_COUNTS)
    batch=result.batch
    if batch:
        vertices={v.vert_key:primitive(v.position) for v in batch.vertices}
        regions={r.semantic_region_id:[] for r in batch.semantic_regions}
        face_values=[]
        for face in batch.faces:
            geom=[cycle([[vertices[u.vert_key],primitive(u.uv)] for u in face.uv_facts]),primitive(face.material_id),provenance(face.provenance)]
            regions[face.semantic_region_id].append(geom)
            face_values.append(geom)
        capture['geometry_values']={
            'vertices':sorted([[primitive(v.position),provenance(v.provenance)] for v in batch.vertices],key=repr),
            'faces':sorted(face_values,key=repr),
            'regions':sorted([sorted(fs,key=repr) for fs in regions.values()],key=repr),
            'stations':sorted([[vertices[s.vert_key],primitive(s.source_s),primitive(s.source_r),primitive(s.station_model_id)] for s in batch.station_facts],key=repr),
            'boundary_chains':sorted([[vertices[k] for k in c.ordered_vert_keys] for c in batch.boundary_chains],key=repr),
            'interface_chains':sorted([[vertices[k] for k in c.ordered_vert_keys] for c in batch.interface_chains],key=repr),
        }
        capture['batch']=primitive(batch)
    return result
material.materialize_domain=observed
record={'root':str(root),'kernel_code_identity':g['record']['kernel_code_identity'],'topology':'TRIANGLES_V1','rational_control_patch':2,'rows':[]}
for density in (1,2,4):
    for patch_id in (0,1,2,6,7,17,105,106,109):
        trace.clear();aliases.clear();capture.clear();canon.reset_sign_counts()
        row=sweep.compute_row(patch_id,density)
        row['evidence']=dict(capture);row['identity_trace']=dict(trace)
        record['rows'].append(row)
        with gzip.open(str(out)+'.gz','wt',encoding='utf8') as f:json.dump(record,f)
    print('completed material',density,flush=True)
print('FINISHED',len(record['rows']),flush=True)

