from pathlib import Path
import sys,json,hashlib,dataclasses
from decimal import Decimal
root=Path(sys.argv[1]);out=Path(sys.argv[2])
sys.path[:0]=[str(root/'kernel/src'),str(root/'kernel/tests')]
from reference_factories import straight_snapshot
from test_contact_candidates_memo import CONCAVE
from cftuv_envelope.reference import compile_reference_envelopes,evaluate_reference_raw_coverage,boundary,strip,native_exact as nx
from cftuv_envelope import exact_sqrt_sum as canon
from cftuv_envelope.reference.planar_types import ExactScalar
trace={}
def val(text):
    n=nx.native_of_text(text)
    return str(n.terms) if len(n.terms)>1 else (['Q',0,1] if not n.terms else ['SQUARE',n.signum(),str(n*n)])
def spy(module):
    original=module.stable_id
    def call(*args):
        result=original(*args)
        if args[0] in ('boundary-contact','envelope-instance'):
            trace[result]={'kind':args[0],'args':list(map(str,args[:-1])),'text':args[-1],'value':val(args[-1]),'id':result}
        return result
    module.stable_id=call
spy(boundary);spy(strip)
def point(p):return [p.x.expression,p.y.expression]
def geometry(raw):
    verts={v.vertex_id:point(v.point) for v in raw.vertices}
    edges={e.edge_id:[verts[e.start_vertex_id],verts[e.end_vertex_id]] for e in raw.edges}
    loops={}
    for loop in raw.loops:
        cycle=[edges[e] for e in loop.ordered_edge_ids]
        rotated=min((cycle[i:]+cycle[:i] for i in range(len(cycle))),key=repr) if cycle else []
        loops[loop.loop_id]=[loop.kind.value,rotated,loop.signed_area]
    return {'vertices':sorted(verts.values(),key=repr),'edges':sorted(edges.values(),key=repr),'loops':sorted(loops.values(),key=repr),'regions':sorted([[loops[r.outer_loop_id],sorted([loops[h] for h in r.hole_loop_ids],key=repr)] for r in raw.regions],key=repr)}
rows=[]
for matrix in ((1,0,0,1),(1,0,1,1),(2,1,1,2)):
    a,b,c,d=matrix
    def transform(p):x,y=p;return a*x+b*y,c*x+d*y
    for alpha in ('0.45','20'):
        trace.clear();canon.reset_factorization_memory();canon.reset_unbudgeted_work()
        snapshot,request=straight_snapshot(faces=tuple(tuple(map(transform,f)) for f in CONCAVE),source_routes=({'name':'source','points':tuple(map(transform,((0,0),(10,0))))},),alpha=alpha)
        compiled=compile_reference_envelopes(snapshot,request)
        result=evaluate_reference_raw_coverage(compiled.compilation,alpha)
        raw=result.raw_coverage
        row={'matrix':matrix,'alpha':alpha,'outcome':result.outcome.value,'trace':list(trace.values()),'raw':None,'unbudgeted':canon.UNBUDGETED_WORK.spent}
        if raw:
            row['raw']={'semantic_digest':raw.semantic_digest,'area':raw.exact_area_expression,'geometry':geometry(raw),'components':sorted([[x.front_component_id,x.effective_alpha.expression,x.capacity_outcome.value if x.capacity_outcome else None] for x in raw.component_effective_alphas]),'ids':{name:sorted(getattr(x,field) for x in getattr(raw,name)) for name,field in {'vertices':'vertex_id','edges':'edge_id','loops':'loop_id','regions':'region_id','envelope_instances':'envelope_instance_id','boundary_vertex_occurrences':'boundary_occurrence_id','point_contacts':'point_contact_id'}.items()}}
        rows.append(row)
        print(matrix,alpha,result.outcome.value,bool(raw),flush=True)
out.write_text(json.dumps({'root':str(root),'rows':rows},indent=2),encoding='utf8')
